function curry3(fn) {
  return (a) => (b) => (c) => fn(a, b, c);
}

function add3(a, b, c) { return a + b + c; }

const curriedAdd3 = curry3(add3);
console.log(curriedAdd3(1)(2)(3));
console.log(curriedAdd3(10)(20)(30));

